"COPY DONATION ADDRESS":{de:"SPENDENADRESSE KOPIEREN",fr:"COPIER L’ADRESSE DE DON",it:"COPIA INDIRIZZO DONAZIONE",ja:"寄付アドレスをコピー","zh-CN":"复制捐赠地址",ru:"КОПИРОВАТЬ АДРЕС ДЛЯ ДОНАТА",tr:"BAĞIŞ ADRESİNİ KOPYALA",hi:"दान का पता कॉपी करें"},
