"SYSTEMS OPERATIONAL":{de:"SYSTEME EINSATZBEREIT",fr:"SYSTÈMES OPÉRATIONNELS",it:"SISTEMI OPERATIVI",ja:"システム稼働中","zh-CN":"系统运行正常",ru:"СИСТЕМЫ РАБОТАЮТ",tr:"SİSTEMLER ÇALIŞIR DURUMDA",hi:"सिस्टम चालू हैं"},
